    export default {
        name: 'c_checkbox',
        props: {
            configObj: {
                type: Object
            },
            configNme: {
                type: String
            }
        },
        data () {
            return {
                formData: {
                    type: 0
                },
                defaults: {},
                configData: {},
				selectedData:[],
				userStyle:0
            }
        },
        watch: {
            configObj: {
                handler (nVal, oVal) {
                    this.defaults = nVal
                    this.configData = nVal[this.configNme]
					this.userStyle = nVal.styleConfig.tabVal
					this.selectedData = nVal.checkboxInfo.type
                },
                deep: true
            },
			'configObj.styleConfig.tabVal':{
				handler(nVal, oVal){
					if(this.configData.userType){
						this.configData.type = [3,1,2]
					}
				}
			}
        },
        mounted () {
            this.$nextTick(() => {
                this.defaults = this.configObj;
                this.configData = this.configObj[this.configNme];
				this.userStyle = this.defaults.styleConfig.tabVal
				this.selectedData = this.defaults.checkboxInfo.type
            })
        },
        methods: {
            checkboxChange (e) {
                // this.$emit('getConfig', e);
            }
        }
    }
